#include <print>
#include <vector>

bool ok(const std::vector<int>& rope, int len, int k) {
    int cnt = 0;
    for (int r : rope) cnt += r / len;
    return cnt >= k;
}

int main() {
    std::vector<int> rope = {8, 5, 3, 2};

    {   // 第一跑：k 取 3
        int k = 3, ans = 0;
        int lo = 1, hi = 8;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (ok(rope, mid, k)) { ans = mid; lo = mid + 1; } else hi = mid - 1;
        }
        std::println("剪成 {} 段，每段最长 {} 厘米", k, ans);
    }
    {   // 第二跑：k 取 8
        int k = 8, ans = 0;
        int lo = 1, hi = 8;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (ok(rope, mid, k)) { ans = mid; lo = mid + 1; } else hi = mid - 1;
        }
        std::println("剪成 {} 段，每段最长 {} 厘米", k, ans);
    }
    return 0;
}

