int main() {
    std::vector<int> rope = {8, 5, 3, 2};
    int k = 3, ans = 0;
    for (int len = 1; len <= 8; ++len) {
        int cnt = 0;
        for (int r : rope) cnt += r / len;
        if (cnt >= k) ans = len;
    }
    std::println("每段最长 {} 厘米", ans);
    return 0;
}
